  @doc "String and math functions. Local may refuse these by name."
  @spec functions_values_refusable() :: [tuple()]
  def functions_values_refusable do
    [
      {:sel, "pow(1.0e300 * 1.0e300, 2.0)", :ok,
       [nil, nil, nil, nil, nil, nil, nil, nil, nil, nil, nil, nil]},
      {:sel, "pow(2.0, 1.0e300 * 1.0e300)", :ok,
       [nil, nil, nil, nil, nil, nil, nil, nil, nil, nil, nil, nil]},
      {:sel, "pow(2, 1.0e300 * 1.0e300)", :ok,
       [nil, nil, nil, nil, nil, nil, nil, nil, nil, nil, nil, nil]},
      {:sel, "pow(length(s), 2)", :ok, [4, 4, 4, nil, 4, 4, 4, nil, 4, 4, 4, nil]},
      {:sel, "greatest(length(s), 1)", :ok, [2, 2, 2, 1, 2, 2, 2, 1, 2, 2, 2, 1]},
      {:raw, "SELECT log(CAST(n AS DOUBLE), n) AS r FROM main ORDER BY time", :ok,
       [
         %{"r" => 1.0},
         %{"r" => 1.0},
         %{"r" => 1.0},
         %{"r" => 1.0},
         %{"r" => 1.0},
         %{"r" => 1.0},
         %{"r" => 1.0},
         %{"r" => 1.0},
         %{"r" => 1.0},
         %{"r" => 1.0},
         %{"r" => 1.0},
         %{"r" => 1.0}
       ]},
      {:raw, "SELECT log(CAST(x AS DOUBLE), x) AS r FROM main ORDER BY time", :ok,
       [
         %{"r" => nil},
         %{"r" => 1.0},
         %{"r" => 1.0},
         %{"r" => 1.0},
         %{"r" => 1.0},
         %{"r" => 1.0},
         %{"r" => 1.0},
         %{},
         %{"r" => 1.0},
         %{"r" => 1.0},
         %{"r" => 1.0},
         %{"r" => 1.0}
       ]},
      {:raw, "SELECT log(u, u) AS r FROM mext ORDER BY time", :ok,
       [%{"r" => 1.0}, %{"r" => 1.0}, %{"r" => 1.0}]}
    ]
  end

