      {:raw, "SELECT count(*) AS c FROM main WHERE s ~ '\\x73'", :ok, [%{"c" => 9}]},
      {:raw, "SELECT count(*) AS c FROM main WHERE s ~ 's'", :ok, [%{"c" => 9}]},
      {:raw, "SELECT count(*) AS c FROM main WHERE s ~ '[[:alpha:]]'", :ok, [%{"c" => 9}]},
