      {:raw, "SELECT count(*) AS c FROM main WHERE s ~ '\\1'", :error, 500,
       "Optimizer rule 'simplify_expressions' failed\ncaused by\nInvalid regex\ncaused by\nExternal error: regex parse error:\n    \\1\n    ^^\nerror: backreferences are not supported"},
      {:raw, "SELECT count(*) AS c FROM main WHERE s ~ '\\0'", :error, 500,
       "Optimizer rule 'simplify_expressions' failed\ncaused by\nInvalid regex\ncaused by\nExternal error: regex parse error:\n    \\0\n    ^^\nerror: backreferences are not supported"},
      {:raw, "SELECT count(*) AS c FROM main WHERE s ~ '\\p{Foo}'", :error, 500,
       "Optimizer rule 'simplify_expressions' failed\ncaused by\nInvalid regex\ncaused by\nExternal error: regex parse error:\n    \\p{Foo}\n    ^^^^^^^\nerror: Unicode property not found"},
      {:raw, "SELECT count(*) AS c FROM main WHERE s ~ '\\p{Script=Foo}'", :error, 500,
       "Optimizer rule 'simplify_expressions' failed\ncaused by\nInvalid regex\ncaused by\nExternal error: regex parse error:\n    \\p{Script=Foo}\n    ^^^^^^^^^^^^^^\nerror: Unicode property value not found"},
      {:raw, "SELECT count(*) AS c FROM main WHERE s ~ '\\p{Foo=Bar}'", :error, 500,
       "Optimizer rule 'simplify_expressions' failed\ncaused by\nInvalid regex\ncaused by\nExternal error: regex parse error:\n    \\p{Foo=Bar}\n    ^^^^^^^^^^^\nerror: Unicode property not found"},
      {:raw, "SELECT count(*) AS c FROM main WHERE s ~ '\\p{L'", :error, 500,
       "Optimizer rule 'simplify_expressions' failed\ncaused by\nInvalid regex\ncaused by\nExternal error: regex parse error:\n    \\p{L\n        ^\nerror: incomplete escape sequence, reached end of pattern prematurely"},
      {:raw, "SELECT count(*) AS c FROM main WHERE s ~ '\\p'", :error, 500,
       "Optimizer rule 'simplify_expressions' failed\ncaused by\nInvalid regex\ncaused by\nExternal error: regex parse error:\n    \\p\n      ^\nerror: incomplete escape sequence, reached end of pattern prematurely"},
      {:raw, "SELECT count(*) AS c FROM main WHERE s ~ '[a'", :error, 500,
       "Optimizer rule 'simplify_expressions' failed\ncaused by\nInvalid regex\ncaused by\nExternal error: regex parse error:\n    [a\n    ^\nerror: unclosed character class"},
      {:raw, "SELECT count(*) AS c FROM main WHERE s ~ '[z-a]'", :error, 500,
       "Optimizer rule 'simplify_expressions' failed\ncaused by\nInvalid regex\ncaused by\nExternal error: regex parse error:\n    [z-a]\n     ^^^\nerror: invalid character class range, the start must be <= the end"},
      {:raw, "SELECT count(*) AS c FROM main WHERE s ~ '[a-\\d]'", :error, 500,
       "Optimizer rule 'simplify_expressions' failed\ncaused by\nInvalid regex\ncaused by\nExternal error: regex parse error:\n    [a-\\d]\n       ^^\nerror: invalid range boundary, must be a literal"},
      {:raw, "SELECT count(*) AS c FROM main WHERE s ~ '[a-\\d-z]'", :error, 500,
       "Optimizer rule 'simplify_expressions' failed\ncaused by\nInvalid regex\ncaused by\nExternal error: regex parse error:\n    [a-\\d-z]\n       ^^\nerror: invalid range boundary, must be a literal"},
      {:raw, "SELECT count(*) AS c FROM main WHERE s ~ '[\\d-z]'", :error, 500,
       "Optimizer rule 'simplify_expressions' failed\ncaused by\nInvalid regex\ncaused by\nExternal error: regex parse error:\n    [\\d-z]\n     ^^\nerror: invalid range boundary, must be a literal"},
      {:raw, "SELECT count(*) AS c FROM main WHERE s ~ '[\\d-\\d]'", :error, 500,
       "Optimizer rule 'simplify_expressions' failed\ncaused by\nInvalid regex\ncaused by\nExternal error: regex parse error:\n    [\\d-\\d]\n     ^^\nerror: invalid range boundary, must be a literal"},
      {:raw, "SELECT count(*) AS c FROM main WHERE s ~ '[\\q]'", :error, 500,
       "Optimizer rule 'simplify_expressions' failed\ncaused by\nInvalid regex\ncaused by\nExternal error: regex parse error:\n    [\\q]\n     ^^\nerror: unrecognized escape sequence"},
      {:raw, "SELECT count(*) AS c FROM main WHERE s ~ '[a\\q]'", :error, 500,
       "Optimizer rule 'simplify_expressions' failed\ncaused by\nInvalid regex\ncaused by\nExternal error: regex parse error:\n    [a\\q]\n      ^^\nerror: unrecognized escape sequence"},
      {:raw, "SELECT count(*) AS c FROM main WHERE s ~ '[\\0]'", :error, 500,
       "Optimizer rule 'simplify_expressions' failed\ncaused by\nInvalid regex\ncaused by\nExternal error: regex parse error:\n    [\\0]\n     ^^\nerror: backreferences are not supported"},
      {:raw, "SELECT count(*) AS c FROM main WHERE s ~ '[\\xAB]'", :ok, [%{"c" => 0}]},
      {:raw, "SELECT count(*) AS c FROM main WHERE s ~ '[\\]'", :error, 500,
       "Optimizer rule 'simplify_expressions' failed\ncaused by\nInvalid regex\ncaused by\nExternal error: regex parse error:\n    [\\]\n    ^\nerror: unclosed character class"},
      {:raw, "SELECT count(*) AS c FROM main WHERE s ~ '\\p{L}{2}'", :ok, [%{"c" => 0}]},
      {:raw, "SELECT count(*) AS c FROM main WHERE s ~ '[\\w-z]'", :error, 500,
       "Optimizer rule 'simplify_expressions' failed\ncaused by\nInvalid regex\ncaused by\nExternal error: regex parse error:\n    [\\w-z]\n     ^^\nerror: invalid range boundary, must be a literal"},
      {:raw, "SELECT count(*) AS c FROM main WHERE s ~ '(?:*a)'", :error, 500,
       "Optimizer rule 'simplify_expressions' failed\ncaused by\nInvalid regex\ncaused by\nExternal error: regex parse error:\n    (?:*a)\n       ^\nerror: repetition operator missing expression"},
      {:raw, "SELECT abs(x => 1) AS r", :error, 400,
       "Error during planning: Function 'abs' does not support named arguments"},
      {:raw, "SELECT length(x => 1) AS r", :error, 400,
       "Error during planning: Function 'character_length' does not support named arguments"},
      {:raw, "SELECT pow(x => 1) AS r", :error, 400,
       "Error during planning: Function 'power' does not support named arguments"},
      {:raw, "SELECT max(a => 1) AS r", :error, 400,
       "Error during planning: Aggregate function 'max' does not support named arguments"},
      {:raw, "SELECT stddev_samp(x => 1) AS r", :error, 400,
       "Error during planning: Aggregate function 'stddev' does not support named arguments"},
      {:raw, "SELECT var_samp(x => 1) AS r", :error, 400,
       "Error during planning: Aggregate function 'var' does not support named arguments"},
      {:raw, "SELECT CAST(n AS DOUBLE PRECISION) AS r FROM main WHERE n = 1", :ok,
       [%{"r" => 1.0}]},
      {:raw, "SELECT CAST(n AS VARCHAR(10)) AS r FROM main WHERE n = 1", :ok, [%{"r" => "1"}]},
      {:raw, "SELECT CAST(n AS INT SIGNED) AS r FROM main WHERE n = 1", :ok, [%{"r" => 1}]},
      {:raw, "SELECT CAST(x AS TINYINT) AS r FROM main WHERE n = 1", :ok, [%{"r" => 1}]},
      {:raw, "SELECT n::BIGINT AS r FROM main WHERE n = 1", :ok, [%{"r" => 1}]},
      {:raw, "SELECT CAST(n AS CHAR(0)) AS r FROM main WHERE n = 1", :ok, [%{"r" => "1"}]},
      {:raw, "SELECT CAST(n AS INT(99999999999)) AS r FROM main WHERE n = 1", :ok, [%{"r" => 1}]},
      {:raw, "SELECT CAST(n AS VARCHAR(1,)) AS r FROM main WHERE n = 1", :error, 400,
       "SQL error: ParserError(\"Expected: ), found: , at Line: 1, Column: 27\")"},
      {:raw, "SELECT CAST(n AS INT ARRAY) AS r FROM main WHERE n = 1", :error, 400,
       "SQL error: ParserError(\"Expected: ), found: ARRAY at Line: 1, Column: 22\")"},
      {:raw, "SELECT n::INT ARRAY FROM main WHERE n = 1", :ok, [%{"array" => 1}]},
      {:raw, "SELECT CAST(n AS 5) AS r FROM main", :error, 400,
       "SQL error: ParserError(\"Expected: a data type name, found: 5 at Line: 1, Column: 18\")"}
    ]
  end

  @doc "What the engine says of a type error, an arity error or a failure only a value shows. Local may refuse these by name."
  @spec errors_refusable() :: [tuple()]
  def errors_refusable do
    [
      {:sel, "coalesce(x, s)", :closed},
      {:sel, "coalesce(s, n, x)", :closed},
      {:sel, "nullif(host, n)", :closed},
      {:sel, "greatest(b, n)", :error, 400,
       "Error during planning: Execution error: Function 'greatest' user-defined coercion failed with \"Error during planning: Cannot find a common type for arguments\" No function matches the given name and argument types 'greatest(Boolean, Int64)'. You might need to add explicit type casts.\n\tCandidate functions:\n\tgreatest(UserDefined)"},
      {:sel, "least(time, 1)", :error, 400,
       "Error during planning: Execution error: Function 'least' user-defined coercion failed with \"Error during planning: Cannot find a common type for arguments\" No function matches the given name and argument types 'least(Timestamp(ns), Int64)'. You might need to add explicit type casts.\n\tCandidate functions:\n\tleast(UserDefined)"},
      {:sel, "lower(time)", :error, 400,
       "Error during planning: Internal error: Expect TypeSignatureClass::Native(LogicalType(Native(String), String)) but received NativeType::Timestamp(Nanosecond, None), DataType: Timestamp(ns).\nThis issue was likely caused by a bug in DataFusion's code. Please help us to resolve this by filing a bug report in our issue tracker: https://github.com/apache/datafusion/issues No function matches the given name and argument types 'lower(Timestamp(ns))'. You might need to add explicit type casts.\n\tCandidate functions:\n\tlower(Coercion(TypeSignatureClass::Native(LogicalType(Native(String), String))))"},
      {:sel, "CASE WHEN b THEN time ELSE 1 END", :error, 400,
       "type_coercion\ncaused by\nError during planning: Failed to coerce then (Timestamp(ns)) and else (Int64) to common types in CASE WHEN expression"},
      {:sel, "CASE WHEN b THEN time ELSE 's' END", :error, 500,
       "Optimizer rule 'simplify_expressions' failed\ncaused by\nArrow error: Parser error: Error parsing timestamp from 's': timestamp must contain at least 10 characters"},
      {:sel, "starts_with(time, 'a')", :error, 400,
       "Error during planning: Internal error: Expect TypeSignatureClass::Native(LogicalType(Native(String), String)) but received NativeType::Timestamp(Nanosecond, None), DataType: Timestamp(ns).\nThis issue was likely caused by a bug in DataFusion's code. Please help us to resolve this by filing a bug report in our issue tracker: https://github.com/apache/datafusion/issues No function matches the given name and argument types 'starts_with(Timestamp(ns), Utf8)'. You might need to add explicit type casts.\n\tCandidate functions:\n\tstarts_with(Coercion(TypeSignatureClass::Native(LogicalType(Native(String), String))), Coercion(TypeSignatureClass::Native(LogicalType(Native(String), String))))"},
      {:sel, "greatest(1, 'a')", :error, 500,
       "Optimizer rule 'simplify_expressions' failed\ncaused by\nArrow error: Cast error: Cannot cast string 'a' to value of Int64 type"},
      {:sel, "greatest(n, true)", :error, 400,
       "Error during planning: Execution error: Function 'greatest' user-defined coercion failed with \"Error during planning: Cannot find a common type for arguments\" No function matches the given name and argument types 'greatest(Int64, Boolean)'. You might need to add explicit type casts.\n\tCandidate functions:\n\tgreatest(UserDefined)"},
      {:sel, "substr('a')", :error, 400,
       "Error during planning: Substring without for/from is not valid Substring { expr: Value(ValueWithSpan { value: SingleQuotedString(\"a\"), span: Span(Location(1,15)..Location(1,18)) }), substring_from: None, substring_for: None, special: false, shorthand: false }"},
      {:sel, "greatest(s, n)", :closed},
      {:sel, "least(s, b)", :error, 400,
       "Error during planning: Execution error: Function 'least' user-defined coercion failed with \"Error during planning: Cannot find a common type for arguments\" No function matches the given name and argument types 'least(Utf8, Boolean)'. You might need to add explicit type casts.\n\tCandidate functions:\n\tleast(UserDefined)"},
      {:sel, "greatest(x, n, s)", :closed},
      {:where, "substr(s) = 'a'", :error, 400,
       "Error during planning: Substring without for/from is not valid Substring { expr: Identifier(Ident { value: \"s\", quote_style: None, span: Span(Location(1,33)..Location(1,34)) }), substring_from: None, substring_for: None, special: false, shorthand: false }"},
      {:where, "greatest(s, n) = 1", :closed},
      {:order, "substr(s)", :error, 400,
       "Error during planning: Substring without for/from is not valid Substring { expr: Identifier(Ident { value: \"s\", quote_style: None, span: Span(Location(1,36)..Location(1,37)) }), substring_from: None, substring_for: None, special: false, shorthand: false }"},
      {:order, "greatest(s, n)", :closed},
      {:raw, "SELECT CAST(substr(s) AS INT) FROM main", :error, 400,
       "Error during planning: Substring without for/from is not valid Substring { expr: Identifier(Ident { value: \"s\", quote_style: None, span: Span(Location(1,20)..Location(1,21)) }), substring_from: None, substring_for: None, special: false, shorthand: false }"},
      {:raw, "SELECT substr(s) IS NULL FROM main", :error, 400,
       "Error during planning: Substring without for/from is not valid Substring { expr: Identifier(Ident { value: \"s\", quote_style: None, span: Span(Location(1,15)..Location(1,16)) }), substring_from: None, substring_for: None, special: false, shorthand: false }"},
      {:sel, "CASE WHEN s THEN 1 END", :closed},
      {:sel, "CASE WHEN n > 1 THEN 1 WHEN n > 2 THEN true ELSE 3 END", :error, 400,
       "type_coercion\ncaused by\nError during planning: Failed to coerce then (Int64, Boolean) and else (Int64) to common types in CASE WHEN expression"},
      {:sel, "coalesce(n, s)", :closed},
      {:sel, "coalesce(n, x, s)", :closed},
      {:sel, "coalesce(host, 1)", :closed},
      {:sel, "nullif(n, s)", :closed},
      {:sel, "nullif(s, 1)", :closed},
      {:sel, "nullif(x, s)", :closed},
      {:sel, "time = 'abc'", :error, 500,
       "Optimizer rule 'simplify_expressions' failed\ncaused by\nArrow error: Parser error: Error parsing timestamp from 'abc': timestamp must contain at least 10 characters"},
      {:where, "s LIKE n", :error, 400,
       "type_coercion\ncaused by\nError during planning: There isn't a common type to coerce Utf8 and Int64 in LIKE expression"},
      {:where, "coalesce(n, s) > 1", :closed},
      {:where, "nullif(n, s) > 1", :closed},
      {:where, "time > n", :error, 400,
       "type_coercion\ncaused by\nError during planning: Cannot infer common argument type for comparison operation Timestamp(ns) > Int64"},
      {:where, "time < x", :error, 400,
       "type_coercion\ncaused by\nError during planning: Cannot infer common argument type for comparison operation Timestamp(ns) < Float64"},
      {:order, "coalesce(n, s)", :closed},
      {:order, "nullif(n, s)", :closed},
      {:sel, "x IS UNKNOWN", :error, 400,
       "type_coercion\ncaused by\nError during planning: Cannot infer common argument type for comparison operation Float64 IS DISTINCT FROM Boolean"},
      {:sel, "CASE time WHEN 's' THEN 'a' END", :error, 500,
       "Optimizer rule 'simplify_expressions' failed\ncaused by\nArrow error: Parser error: Error parsing timestamp from 's': timestamp must contain at least 10 characters"},
      {:sel, "CASE time WHEN s THEN 'a' END", :closed},
      {:sel, "CASE s WHEN time THEN 'a' END", :closed},
      {:sel, "CASE host WHEN time THEN 'a' END", :closed},
      {:raw, "replace into m values (1)", :error, 400,
       "Error during planning: table 'public.iox.m' not found"},
      {:raw, "select +s from main limit 1", :error, 400,
       "Error during planning: Unary operator '+' only supports numeric, interval and timestamp types"},
      {:raw, "select starts_with(NULL,time) from main", :error, 400,
       "Error during planning: Internal error: Expect TypeSignatureClass::Native(LogicalType(Native(String), String)) but received NativeType::Timestamp(Nanosecond, None), DataType: Timestamp(ns).\nThis issue was likely caused by a bug in DataFusion's code. Please help us to resolve this by filing a bug report in our issue tracker: https://github.com/apache/datafusion/issues No function matches the given name and argument types 'starts_with(Null, Timestamp(ns))'. You might need to add explicit type casts.\n\tCandidate functions:\n\tstarts_with(Coercion(TypeSignatureClass::Native(LogicalType(Native(String), String))), Coercion(TypeSignatureClass::Native(LogicalType(Native(String), String))))"},
      {:raw, "select starts_with(time,NULL) from main", :error, 400,
       "Error during planning: Internal error: Expect TypeSignatureClass::Native(LogicalType(Native(String), String)) but received NativeType::Timestamp(Nanosecond, None), DataType: Timestamp(ns).\nThis issue was likely caused by a bug in DataFusion's code. Please help us to resolve this by filing a bug report in our issue tracker: https://github.com/apache/datafusion/issues No function matches the given name and argument types 'starts_with(Timestamp(ns), Null)'. You might need to add explicit type casts.\n\tCandidate functions:\n\tstarts_with(Coercion(TypeSignatureClass::Native(LogicalType(Native(String), String))), Coercion(TypeSignatureClass::Native(LogicalType(Native(String), String))))"},
      {:raw, "SELECT NULL - time - time AS r FROM main", :error, 400,
       "Error during planning: Cannot coerce arithmetic expression Duration(ns) - Timestamp(ns) to valid types"},
      {:raw, "SELECT v FROM main WHERE NULL - time > 0", :error, 400,
       "type_coercion\ncaused by\nError during planning: Cannot infer common argument type for comparison operation Duration(ns) > Int64"},
      {:raw, "SELECT coalesce(NULL + NULL, s) AS r FROM main ORDER BY time", :closed},
      {:raw, "SELECT max(+NULL) AS r FROM main", :error, 400,
       "Error during planning: Unary operator '+' only supports numeric, interval and timestamp types"},
      {:raw, "SELECT avg(+NULL) AS r FROM main", :error, 400,
       "Error during planning: Unary operator '+' only supports numeric, interval and timestamp types"},
      {:raw, "SELECT count(+NULL) AS r FROM main", :error, 400,
       "Error during planning: Unary operator '+' only supports numeric, interval and timestamp types"},
      {:raw, "SELECT approx_median(-NULL) AS r FROM main", :ok, [%{}]},
      {:raw, "SELECT v FROM main WHERE NULL - time > 0 ORDER BY time", :error, 400,
       "type_coercion\ncaused by\nError during planning: Cannot infer common argument type for comparison operation Duration(ns) > Int64"},
      {:raw, "SELECT v FROM main WHERE time - NULL > 0 ORDER BY time", :error, 400,
       "type_coercion\ncaused by\nError during planning: Cannot infer common argument type for comparison operation Duration(ns) > Int64"},
      {:raw, "SELECT coalesce(NULL + NULL, s) AS r FROM main ORDER BY time LIMIT 1", :closed},
      {:raw, "SELECT coalesce(NULL - NULL, s) AS r FROM main ORDER BY time LIMIT 1", :closed},
      {:raw, "SELECT coalesce(NULL + NULL, host) AS r FROM main ORDER BY time LIMIT 1", :closed},
